//! The public seam of the core.
//!
//! Everything in this module is the schema authority for three things at once:
//!
//! 1. the FFI surface (UniFFI → Kotlin, napi-rs → Node) — commands, queries and
//!    events cross the seam as JSON strings and the platform side gets typed
//!    bindings generated by `typeshare` from these definitions;
//! 2. the Connect wire protocol (JSON over WebSocket), see [`crate::connect::wire`];
//! 3. everything persisted that isn't a mirror table (session document, saved
//!    queues, settings, config backup).
//!
//! Rules for this file:
//! - Every type is `#[typeshare]` and `serde` round-trippable. Enums with data use
//!   adjacent tagging (`tag = "type", content = "data"`) because typeshare needs it.
//! - No `u64`/`i64` (TypeScript can't represent them). Milliseconds are `u32`
//!   for durations/positions, `f64` for epoch timestamps.
//! - No tuples, no `serde_json::Value`. Opaque JSON travels as a `String`.
//! - Additive changes only once shipped: new fields are `Option` or have
//!   `#[serde(default)]`, and unknown fields are preserved by the document
//!   types that carry `extra` (older devices must round-trip newer state).
//! - `Option` fields serialise as `null`, never as an absent key (serde's
//!   default, and nothing here uses `skip_serializing_if` on an `Option`).
//!   TypeScript consumers should test `== null`, not `in` / `undefined`.
//! - Local paths (`MediaSessionMetadata::artwork_path`, `QueryResult::Path`)
//!   are plain filesystem paths without a scheme; `MediaSource::url` is the
//!   one place a `file://` URL travels.
//!
//! The core is an actor: [`Command`]s in, [`Event`]s out, [`Query`]s are async
//! request/response and never expose interior state synchronously.

use std::collections::HashMap;

use serde::{Deserialize, Serialize};
use typeshare::typeshare;

/// Schema version of everything in this file. Bump on incompatible change;
/// additive changes don't need it.
pub const API_SCHEMA_VERSION: u32 = 1;
/// Protocol floor below which the Connect handshake refuses to talk.
/// Aliases of the wire constants so the two can never drift apart.
pub const PROTOCOL_MIN_VERSION: u32 = crate::connect::wire::PROTOCOL_MIN;
/// Connect wire protocol spoken by this build (2 added mutual LAN auth).
pub const PROTOCOL_VERSION: u32 = crate::connect::wire::PROTOCOL;

// ---------------------------------------------------------------------------
// Identity
// ---------------------------------------------------------------------------

#[typeshare]
pub type ServerId = String;
#[typeshare]
pub type TrackId = String;
#[typeshare]
pub type AlbumId = String;
#[typeshare]
pub type ArtistId = String;
#[typeshare]
pub type PlaylistId = String;
#[typeshare]
pub type DeviceId = String;
#[typeshare]
pub type SessionId = String;
#[typeshare]
pub type JobId = String;
#[typeshare]
pub type FilterId = String;
/// Unique per queue *instance* of a track: the same track queued twice has two keys.
#[typeshare]
pub type QueueKey = String;
/// Epoch milliseconds, on the local monotonic-ish wall clock unless stated otherwise.
#[typeshare]
pub type EpochMs = f64;
/// Duration or position in milliseconds.
#[typeshare]
pub type Ms = u32;

// ---------------------------------------------------------------------------
// Configuration
