#[typeshare]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct CoreConfig {
    /// Root for the SQLite mirror, downloads, caches, logs. Created if missing.
    pub data_dir: String,
    /// Separate directory for the evictable stream cache (may be on a different volume).
    pub cache_dir: String,
    pub device_id: DeviceId,
    pub device_name: String,
    pub platform: Platform,
    pub app_version: String,
    /// Whether this process owns audio itself (`native-audio` feature; desktop) or
    /// drives an external backend through [`Event::Backend`] (Android / Media3).
    pub audio: AudioMode,
    /// Present when running as the headless coordinator. The coordinator never
    /// plays audio and never holds credentials.
    #[serde(default)]
    pub coordinator_listen: Option<String>,
}

#[typeshare]
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum Platform {
    Android,
    Linux,
    MacOs,
    Windows,
    Coordinator,
}

#[typeshare]
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum AudioMode {
    /// Symphonia + cpal inside the core.
    Native,
    /// Platform player (ExoPlayer) driven over the seam.
    External,
    /// No audio at all (coordinator, tests).
    None,
}

