/// What an `Event::PlayerNotice` is about, stable across releases and
/// languages (the `message` text is neither).
#[typeshare]
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum PlayerNoticeCode {
    /// Offline: tracks neither downloaded nor fully cached are skipped.
    OfflineSkipping,
    /// Offline, and nothing left in the queue plays here: playback stopped.
    NothingAvailableOffline,
    /// No server connection to stream from.
    NoServer,
    /// A non-fatal playback problem (`detail`: the backend's message).
    PlaybackProblem,
    /// A track failed to play and was skipped (`detail`: its title).
    CouldNotPlaySkipped,
    /// Stopped after several unplayable tracks in a row (`detail`: the last title).
    CouldNotPlayStopped,
    /// Autoplay was asked for more and found nothing to add.
    AutoplayFoundNothing,
}

#[typeshare]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", tag = "type", content = "data")]
pub enum Event {
    /// Emitted exactly once per core, when `Start` completes. Platforms key
    /// one-time work (credential replay, first-run setup) on this.
    Started {
        snapshot: Snapshot,
    },
    /// Emitted by `RequestSnapshot` (and by anything else that re-emits the
    /// whole state, such as `RemoveServer`) ahead of the `*Changed` replay.
    /// Same payload as `Started`, never confused with it.
    Snapshot {
        snapshot: Snapshot,
    },
    ServersChanged {
        servers: Vec<ServerInfo>,
    },
    SyncProgress {
        progress: SyncProgress,
    },
    /// Mirror tables changed; UIs should refetch visible queries. Empty = everything.
    LibraryChanged {
        server_id: ServerId,
        tables: Vec<String>,
        ids: Vec<String>,
    },
    SearchResults {
        results: SearchResults,
    },
    /// Ratings or loves changed: set here (including undo and the rating →
    /// love bridge) or, with `from_device`, on another signed-in device and
    /// relayed through Connect. The mirror already holds these values, so
    /// UIs patch every copy of the item they show (rows, detail headers,
    /// search results, menus) in place. Followed by a `LibraryChanged` for
    /// list refetches and, when the item is queued, by `NowPlayingChanged` /
    /// `QueueChanged` / `MediaSession`. A library sync that picks up changes
    /// made elsewhere reports them with `LibraryChanged` only.
    LibraryItemsChanged {
        server_id: ServerId,
        items: Vec<LibraryItemState>,
        /// The device the change came from; `None` for this one.
        #[serde(default)]
        from_device: Option<DeviceId>,
    },
    /// A playlist changed (tracks added, removed or moved, renamed, created
    /// or deleted), here or, with `from_device`, on another signed-in device.
    /// `playlist` is the mirror's row now; `None` when it was deleted.
    /// Screens showing it (its detail page, playlist lists and pickers)
    /// refetch its tracks. Followed by a `LibraryChanged`.
    PlaylistChanged {
        server_id: ServerId,
        playlist_id: PlaylistId,
        playlist: Option<Playlist>,
        #[serde(default)]
        from_device: Option<DeviceId>,
    },

    SessionChanged {
        document: SessionDocument,
    },
    QueueChanged {
        queue: QueueView,
    },
    TransportChanged {
        transport: TransportState,
    },
    /// The item now playing (or `None` when stopped), with a resolved track.
    NowPlayingChanged {
        entry: Option<QueueEntry>,
    },
    SavedQueuesChanged {
        queues: Vec<SavedQueue>,
    },
    UndoChanged {
        state: UndoState,
    },
    Toast {
        toast: Toast,
    },
    /// Inline player-bar line for a non-fatal playback issue ("Couldn't play X, skipped").
    /// `message` is the core's English text; platforms that show their own
    /// (localised) text match on `code` and fill in `detail`. All `None`
    /// clears the line.
    PlayerNotice {
        message: Option<String>,
        #[serde(default)]
        code: Option<PlayerNoticeCode>,
        /// The variable part of the notice: the track's title for
        /// `couldNotPlaySkipped` / `couldNotPlayStopped`, the backend's
        /// message for `playbackProblem`; `None` for the others.
        #[serde(default)]
        detail: Option<String>,
    },

    JobsChanged {
        jobs: Vec<Job>,
    },
    ProblemsChanged {
        problems: Vec<Problem>,
    },

    ConnectionChanged {
        state: ConnectionState,
    },
    /// The network the platform last reported with `SetNetworkState`
    /// (`Snapshot.network`): emitted whenever it changes and in every
    /// replay. `None` until the platform first reports one.
    NetworkChanged {
        network: Option<NetworkState>,
    },
    DevicesChanged {
        devices: Vec<DeviceInfo>,
    },
    HandoffPickerChanged {
        open: bool,
        targets: Vec<DeviceInfo>,
    },
    ResumeOfferChanged {
        offer: Option<ResumeOffer>,
    },

    LyricsChanged {
        track_id: TrackId,
        lyrics: Option<Lyrics>,
    },
    PinsChanged {
        pins: Vec<Pin>,
    },
    StorageChanged {
        storage: StorageSummary,
    },
    FiltersChanged {
        filters: Vec<Filter>,
    },
    SettingChanged {
        setting: Setting,
    },
    AudioSettingsChanged {
        settings: AudioSettings,
    },
    OutputDevicesChanged {
        devices: Vec<OutputDevice>,
    },
    SleepTimerChanged {
        timer: Option<SleepTimer>,
    },
    ShortcutsChanged {
        shortcuts: Vec<Shortcut>,
    },
    ActionsChanged {
        surface: String,
    },
    NspExported {
        filter_id: FilterId,
        document: String,
        path: Option<String>,
    },
    ConfigExported {
        document: String,
    },

    /// Drive an external backend (Android). Not emitted in native mode.
    Backend {
        command: BackendCommand,
    },
    /// Drive the OS media session (both platforms).
    MediaSession {
        state: MediaSessionState,
    },

    Error {
        kind: ErrorKind,
        message: String,
        detail: Option<String>,
    },
    Log {
        level: String,
        target: String,
        message: String,
    },
}

// ---------------------------------------------------------------------------
// Config backup document
// ---------------------------------------------------------------------------

#[typeshare]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct ConfigDocument {
    pub version: u32,
    pub exported_at: EpochMs,
    pub settings: Vec<Setting>,
    pub filters: Vec<Filter>,
    pub shortcuts: Vec<Shortcut>,
    pub servers: Vec<ServerInfo>,
    /// Only present when exported with secrets; encrypted at rest by the platform keystore otherwise.
    pub secrets: Option<HashMap<String, String>>,
    pub audio: AudioSettings,
    pub autoplay: AutoplaySettings,
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub extra: HashMap<String, String>,
}

#[cfg(test)]
mod redaction_tests {
    use super::*;

    #[test]
    fn command_debug_never_shows_the_password_and_kind_is_the_wire_tag() {
        let cmd = Command::AddServer {
            url: "https://music.example/".into(),
            username: "alice".into(),
            password: "hunter2".into(),
            name: None,
        };
        let dbg = format!("{cmd:?}");
        assert!(!dbg.contains("hunter2"), "{dbg}");
        assert!(dbg.contains("<redacted>"), "{dbg}");
        assert_eq!(cmd.kind(), "addServer");
        assert_eq!(Command::Start.kind(), "start");
        // The wire shape is unchanged: a plain string.
        let json = serde_json::to_string(&cmd).unwrap();
        assert!(json.contains(r#""password":"hunter2""#), "{json}");
        let back: Command = serde_json::from_str(&json).unwrap();
        assert_eq!(back, cmd);
    }

    #[test]
    fn media_source_debug_strips_the_query_string() {
        let source = MediaSource {
            key: "k1".into(),
            track: TrackSummary::default(),
            url: "https://music.example/rest/stream?id=t0&u=alice&t=abc123&s=salt".into(),
            headers: [("Authorization".to_string(), "Bearer xyz".to_string())].into(),
            mime_type: None,
            gain_db: 0.0,
            transcoded: false,
        };
        let dbg = format!("{source:?}");
        assert!(dbg.contains("https://music.example/rest/stream"), "{dbg}");
        assert!(
            !dbg.contains("abc123") && !dbg.contains("salt") && !dbg.contains("xyz"),
            "{dbg}"
        );
        let cmd = BackendCommand::Load {
            source,
            next: None,
            position_ms: 0,
            play: true,
        };
        assert!(!format!("{cmd:?}").contains("abc123"));
        assert_eq!(redact_url("file:///tmp/a.flac"), "file:///tmp/a.flac");
        assert_eq!(redact_url("https://h/p#frag"), "https://h/p");
    }
}
